   153→  private static DimensionsSpec computeDimensionsSpec(
   154→      TimestampSpec timestampSpec,
   155→      DimensionsSpec dimensionsSpec,
   156→      AggregatorFactory[] aggregators
   157→  )
   158→  {
   159→    final Set<String> dimensionExclusions = new HashSet<>();
   160→
   161→    final String timestampColumn = timestampSpec.getTimestampColumn();
   162→    if (!(dimensionsSpec.hasCustomDimensions() && dimensionsSpec.getDimensionNames().contains(timestampColumn))) {
   163→      dimensionExclusions.add(timestampColumn);
   164→    }
   165→
   166→    for (AggregatorFactory aggregator : aggregators) {
   167→      dimensionExclusions.addAll(aggregator.requiredFields());
   168→      dimensionExclusions.add(aggregator.getName());
   169→    }
   170→
   171→    final Set<String> metSet = Arrays.stream(aggregators).map(AggregatorFactory::getName).collect(Collectors.toSet());
   172→    final Set<String> dimSet = new HashSet<>(dimensionsSpec.getDimensionNames());
   173→    final Set<String> overlap = Sets.intersection(metSet, dimSet);
   174→    if (!overlap.isEmpty()) {
   175→      throw new IAE(
   176→          "Cannot have overlapping dimensions and metrics of the same name. Please change the name of the metric. Overlap: %s",
   177→          overlap
   178→      );
   179→    }
   180→
   181→    return dimensionsSpec.withDimensionExclusions(Sets.difference(dimensionExclusions, dimSet));
   182→  }
